package com.shahabsystem.livewebwallpaper;
import android.app.*;import android.app.WallpaperManager;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity { LinearLayout l; EditText url; SeekBar sp,cp,dim,zoom; Spinner mode; TextView tv(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(15);t.setPadding(0,8,0,5);return t;} SeekBar bar(int v){SeekBar s=new SeekBar(this);s.setMax(100);s.setProgress(v);return s;} Spinner spin(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;} @Override public void onCreate(Bundle b){super.onCreate(b);l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(22,16,22,24);ScrollView sv=new ScrollView(this);sv.addView(l);setContentView(sv);l.addView(tv("LiveWebWallpaper 5.0"));l.addView(tv("Matrix / Code / Web"));l.addView(tv("حالت"));mode=spin(new String[]{"Web","Matrix","Code"});l.addView(mode);l.addView(tv("آدرس Web"));url=new EditText(this);url.setSingleLine();l.addView(url);l.addView(tv("سرعت Matrix"));sp=bar(Prefs.speed(this));l.addView(sp);l.addView(tv("سرعت تایپ Code"));cp=bar(Prefs.codeSpeed(this));l.addView(cp);l.addView(tv("کم‌رنگی"));dim=bar(Prefs.dim(this));l.addView(dim);l.addView(tv("Zoom وب"));zoom=bar((int)((Prefs.zoom(this)-.5f)/1.5f*100));l.addView(zoom);CheckBox hs=new CheckBox(this);hs.setText("عدم نمایش ScrollBar");hs.setChecked(Prefs.hideScroll(this));l.addView(hs);Button save=new Button(this);save.setText("انتخاب Live Wallpaper");l.addView(save);save.setOnClickListener(v->{getSharedPreferences("p",0).edit().putInt("mode",mode.getSelectedItemPosition()).putInt("speed",Math.max(1,sp.getProgress())).putInt("codeSpeed",Math.max(1,cp.getProgress())).putInt("dim",dim.getProgress()).putFloat("zoom",.5f+zoom.getProgress()/100f*1.5f).putString("url",url.getText().toString().trim()).putBoolean("hideScroll",hs.isChecked()).apply();Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,LiveWallpaperService.class));startActivity(i);});mode.setSelection(Prefs.mode(this));url.setText(Prefs.url(this));}}
